"""
report_generator.py
--------------------
Generates HTML, JSON, and CSV reports from an AnalysisProject. Every report
includes tool version, parser-subset version, source filename, an explicit
timestamp, and a methodology/limitations section so nothing is presented
as more authoritative than it is.
"""
from __future__ import annotations

import csv
import io
import json
from html import escape

from app.core.project import AnalysisProject

LIMITATIONS_TEXT = (
    "This report was generated by a static analyzer covering a documented, restricted "
    "subset of synthesizable Verilog (see docs/RTL_SUPPORTED_FEATURES.md). It does not "
    "perform full elaboration, simulation, or synthesis. Operator and signal counts are "
    "structural counts from the parsed source, not measured timing, area, or power. "
    "Optimization suggestions are limited to single-bit Boolean continuous assignments "
    "and are verified for exact logical equivalence by exhaustive truth-table comparison "
    "before being shown; they are not synthesis-tool-verified netlist transformations. "
    "Latch-risk warnings are based on textual if/else and case/default completeness "
    "checks and may not catch every construct."
)


class ReportGenerator:
    def to_json(self, project: AnalysisProject) -> str:
        data = {
            "metadata": project.metadata(),
            "modules": [],
            "methodology_and_limitations": LIMITATIONS_TEXT,
        }
        for mr in project.modules:
            data["modules"].append({
                "name": mr.module.name,
                "summary": dict(mr.analysis.summary_rows()),
                "operator_counts": mr.analysis.operator_counts,
                "issues": [
                    {"severity": i.severity, "message": i.message, "line": i.line, "category": i.category}
                    for i in mr.analysis.issues
                ],
                "optimization_suggestions": [
                    {
                        "rule_id": s.rule_id,
                        "rule_name": s.rule_name,
                        "signal": s.signal,
                        "original_expr": s.original_expr,
                        "optimized_expr": s.optimized_expr,
                        "explanation": s.explanation,
                        "benefit": s.benefit,
                        "verified": s.verified,
                        "line": s.line,
                    }
                    for s in mr.suggestions
                ],
            })
        return json.dumps(data, indent=2)

    def to_csv(self, project: AnalysisProject) -> str:
        buf = io.StringIO()
        writer = csv.writer(buf)
        writer.writerow(["module", "metric", "value"])
        for mr in project.modules:
            for label, value in mr.analysis.summary_rows():
                writer.writerow([mr.module.name, label, value])
        writer.writerow([])
        writer.writerow(["module", "signal", "rule_id", "original_expr", "optimized_expr", "verified"])
        for mr in project.modules:
            for s in mr.suggestions:
                writer.writerow([mr.module.name, s.signal, s.rule_id, s.original_expr, s.optimized_expr, s.verified])
        return buf.getvalue()

    def to_html(self, project: AnalysisProject, graph_image_paths: dict | None = None) -> str:
        graph_image_paths = graph_image_paths or {}
        meta = project.metadata()
        parts = [f"""<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>RTL Analysis Report - {escape(meta['source_filename'])}</title>
<style>
body {{ font-family: -apple-system, Segoe UI, Arial, sans-serif; margin: 40px; color: #1a1a1a; background:#fafafa; }}
h1 {{ border-bottom: 3px solid #2196F3; padding-bottom: 8px; }}
h2 {{ color: #2196F3; margin-top: 40px; }}
table {{ border-collapse: collapse; width: 100%; margin: 12px 0; background:#fff; }}
th, td {{ border: 1px solid #ddd; padding: 8px 12px; text-align: left; font-size: 14px; }}
th {{ background: #2196F3; color: white; }}
.warning {{ color: #E65100; }}
.error {{ color: #C62828; font-weight: bold; }}
.code {{ font-family: "Courier New", monospace; background:#eee; padding:2px 6px; border-radius:3px; }}
.limitations {{ background:#FFF3E0; border-left: 4px solid #FF9800; padding: 12px 18px; margin-top:30px; }}
.meta {{ color:#666; font-size: 13px; }}
img {{ max-width: 100%; border: 1px solid #ccc; margin-top:10px; }}
</style></head><body>
<h1>RTL Analysis Report</h1>
<p class="meta">{escape(meta['tool_name'])} v{escape(meta['tool_version'])} &middot;
Parser subset v{escape(meta['parser_subset_version'])} &middot;
Source: <span class="code">{escape(meta['source_filename'])}</span> &middot;
Generated: {escape(meta['analysis_timestamp_utc'])}</p>
"""]

        for mr in project.modules:
            parts.append(f"<h2>Module: {escape(mr.module.name)}</h2>")
            parts.append("<table><tr><th>Metric</th><th>Value</th></tr>")
            for label, value in mr.analysis.summary_rows():
                parts.append(f"<tr><td>{escape(label)}</td><td>{escape(value)}</td></tr>")
            parts.append("</table>")

            if mr.analysis.operator_counts:
                parts.append("<h3>Operator usage</h3><table><tr><th>Operator</th><th>Count</th></tr>")
                for op, cnt in mr.analysis.operator_counts.items():
                    parts.append(f"<tr><td>{escape(op)}</td><td>{cnt}</td></tr>")
                parts.append("</table>")

            if mr.analysis.issues:
                parts.append("<h3>Warnings &amp; Errors</h3><table><tr><th>Severity</th><th>Line</th><th>Message</th></tr>")
                for i in mr.analysis.issues:
                    cls = "error" if i.severity == "error" else "warning"
                    parts.append(f"<tr><td class='{cls}'>{escape(i.severity)}</td><td>{i.line or '-'}</td><td>{escape(i.message)}</td></tr>")
                parts.append("</table>")

            if mr.suggestions:
                parts.append("<h3>Optimization suggestions</h3><table><tr><th>Signal</th><th>Rule</th><th>Before</th><th>After</th><th>Verified</th></tr>")
                for s in mr.suggestions:
                    parts.append(
                        f"<tr><td>{escape(s.signal)}</td><td>{escape(s.rule_name)}</td>"
                        f"<td class='code'>{escape(s.original_expr)}</td><td class='code'>{escape(s.optimized_expr)}</td>"
                        f"<td>{escape(s.verified)}</td></tr>"
                    )
                parts.append("</table>")

            img_path = graph_image_paths.get(mr.module.name)
            if img_path:
                parts.append(f"<h3>Circuit graph</h3><img src='{escape(img_path)}' alt='circuit graph for {escape(mr.module.name)}'>")

        parts.append(f"<div class='limitations'><strong>Methodology &amp; Limitations</strong><p>{escape(LIMITATIONS_TEXT)}</p></div>")
        parts.append("</body></html>")
        return "\n".join(parts)
